 const canvas=document.getElementById('world'),stage=document.getElementById('stage'),renderer=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 const scene=new THREE.Scene();scene.background=new THREE.Color('#e6e5d9');const camera=new THREE.OrthographicCamera(-10,10,9,-9,.03,150),controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.dampingFactor=.12;controls.minZoom=.55;controls.maxZoom=12;controls.maxPolarAngle=Math.PI*.495;controls.enablePan=true;
 const hemi=new THREE.HemisphereLight('#f0f5ff','#b0b1be',1.65),sun=new THREE.DirectionalLight('#fffaf3',1.65);sun.position.set(-9,16,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-25,right:25,top:20,bottom:-20,near:1,far:65});sun.shadow.bias=-.00025;sun.shadow.normalBias=.025;sun.shadow.radius=2;const fill=new THREE.DirectionalLight('#e3edf0',.55);fill.position.set(10,9,-10);scene.add(hemi,sun,fill);
