 function setInside(value){if(compareOn)compare(false);inside=!!value;shop=inside?interior:exterior;exterior.root.visible=!inside;interior.root.visible=inside;shop.setRoof(!inside);shop.setCutaway(false);setView(inside?'inside':'hero');sync();return inside;}
