 document.getElementById('enter').onclick=()=>setInside(!inside);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(compareOn)compare(false);setView(b.dataset.view);});document.getElementById('reset').onclick=()=>{const wasInside=inside;if(compareOn)compare(false);setInside(wasInside);};document.getElementById('roof').onclick=()=>{shop.setRoof(!shop.getViewState().roof);sync();};document.getElementById('walls').onclick=()=>{shop.setCutaway(!shop.getViewState().cutaway);sync();};document.getElementById('dim').onclick=()=>setDim(!dim);document.getElementById('compare').onclick=()=>compare(!compareOn);
